/* Reverse a singly linked list in place and return the new head. */
struct node { int value; struct node *next; };

static struct node *reverse(struct node *head) {
    struct node *prev = NULL;
    while (head) {
        struct node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
